        'maharashtra', 'IN-MH', 'Maharashtra', 'महाराष्ट्र', 'Mumbai', 'West', TRUE, 'Land of Sahyadri Forts, UNESCO Cave Temples, Royal Paithani Silks, and Lavani Rhythms', 'From impregnable cliff-top bastions to sacred basalt rock temples, coastal Konkani kitchens, and vibrant folk performing arts.', 'From the ancient Satavahana and Rashtrakuta empires to the 17th-century Hindavi Swarajya established by Chhatrapati Shivaji Maharaj, Maharashtra has stood at the crossroads of military strategy, monumental rock architecture, and deep spiritual traditions.', '{"Marathi","Hindi","Konkani"}', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1200&q=80', 12, 4, 'raigad-fort', 19.7515, 75.7139
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, code=EXCLUDED.code, native_name=EXCLUDED.native_name, capital=EXCLUDED.capital, region=EXCLUDED.region, cultural_identity=EXCLUDED.cultural_identity, short_description=EXCLUDED.short_description, languages=EXCLUDED.languages, banner_image_url=EXCLUDED.banner_image_url, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'konkan', 'maharashtra', 'Konkan Coast', '{"Sindhudurg","Ratnagiri","Raigad","Thane","Palghar","Mumbai"}', 'Coastal rainforest strip celebrated for sea forts, Alfonso mangoes, coconut cuisine, and Warli tribal arts.', 'Maritime forts, Koli fishing lore, Ukadiche Modak, and Malvani spices.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'desh', 'maharashtra', 'Western Ghats / Desh', '{"Pune","Satara","Kolhapur","Sangli","Solapur"}', 'The Sahyadri mountain heartland of Maratha hill bastions, Lavani folk theater, and Kolhapuri leather craftsmanship.', 'Chhatrapati Shivaji Maharaj forts, Puneri Misal, and Tambada Rassa.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'marathwada', 'maharashtra', 'Marathwada', '{"Chhatrapati Sambhajinagar","Jalna","Beed","Nanded","Latur","Dharashiv","Parbhani","Hingoli"}', 'Ancient cradle of world-renowned UNESCO caves (Ajanta & Ellora) and the sacred Godavari spiritual belt.', 'Kailasa monolithic temple, Paithani silk weaving, and Sufi-Bhakti poetry.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
