INSERT INTO states (id, code, name, native_name, capital, region, is_fully_developed, cultural_identity, short_description, historical_overview, languages, banner_image_url, item_count, monument_count, highlighted_item_slug, latitude, longitude) VALUES (
        'assam', 'IN-AS', 'Assam', 'অসম', 'Dispur', 'Northeast', TRUE, 'Gateway to Northeast India, Golden Muga Silk, Majuli River Island, and Rhythmic Bihu Dances', 'Cradle of the mighty Brahmaputra river, ancient Ahom kingdom amphitheaters, Vaishnavite Satra monasteries, and aromatic tea gardens.', 'Ruled unconquered by the Ahom dynasty for nearly 600 years (1228–1826 CE). Assam fostered a unique synthesis of Indo-Tibetan traditions, architectural brick pavilions (Rang Ghar), and the egalitarian Neo-Vaishnavite cultural renaissance pioneered by Srimanta Sankardev.', '{"Assamese","Bodo","Bengali"}', 'https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1200&q=80', 8, 2, 'assam-muga-silk', 26.2006, 92.9376
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, code=EXCLUDED.code, native_name=EXCLUDED.native_name, capital=EXCLUDED.capital, region=EXCLUDED.region, cultural_identity=EXCLUDED.cultural_identity, short_description=EXCLUDED.short_description, languages=EXCLUDED.languages, banner_image_url=EXCLUDED.banner_image_url, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'brahmaputra-valley', 'assam', 'Brahmaputra Valley', '{"Kamrup","Jorhat","Sivasagar","Sonitpur","Dibrugarh"}', 'Fertile river basin harboring historic Ahom royal capitals, tea plantations, and Vaishnavite Satras.', 'Rang Ghar amphitheater, Sivasagar royal tanks, and Sattriya dance monasteries.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'majuli-island', 'assam', 'Majuli River Island', '{"Majuli"}', 'The world’s largest inhabited river island, spiritual heart of Vaishnavite monasteries and Mukha mask artisans.', 'Bamboo mask crafting, Bhaona folk theater, and spiritual chanting.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'barak-valley', 'assam', 'Barak Valley & Hill Tracts', '{"Cachar","Karbi Anglong","Dima Hasao"}', 'Lush undulating hills and valleys with indigenous Dimasa, Karbi, and Bengali heritage.', 'Indigenous handlooms, cane crafts, and harvest songs.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO states (id, code, name, native_name, capital, region, is_fully_developed, cultural_identity, short_description, historical_overview, languages, banner_image_url, item_count, monument_count, highlighted_item_slug, latitude, longitude) VALUES (
        'meghalaya', 'IN-ML', 'Meghalaya', 'Meghalaya (Abode of Clouds)', 'Shillong', 'Northeast', TRUE, 'The Abode of Clouds, Bio-Engineered Living Root Bridges, Sacred Groves, and Matrilineal Traditions', 'High-altitude pine plateaus, majestic waterfalls, ancient living root architectures of the Khasi and Jaintia tribes, and vibrant music festivals.', 'Home to the indigenous Khasi, Garo, and Jaintia peoples who have practiced matrilineal kinship for millennia. Renowned for their deep ecological harmony, preserving sacred groves (Law Kyntang) and engineering living Ficus elastica roots across torrential mountain gorges.', '{"Khasi","Garo","English","Pnar"}', 'https://images.unsplash.com/photo-1627894006066-b45786537123?auto=format&fit=crop&w=1200&q=80', 6, 2, 'meghalaya-living-root-bridge', 25.467, 91.3662
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, code=EXCLUDED.code, native_name=EXCLUDED.native_name, capital=EXCLUDED.capital, region=EXCLUDED.region, cultural_identity=EXCLUDED.cultural_identity, short_description=EXCLUDED.short_description, languages=EXCLUDED.languages, banner_image_url=EXCLUDED.banner_image_url, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'khasi-hills', 'meghalaya', 'East & West Khasi Hills', '{"East Khasi Hills","West Khasi Hills","Ri-Bhoi"}', 'Misty pine plateaus home to Shillong, Cherrapunji (Sohra), and Mawlynnong clean village.', 'Living root bridges, Mawphlang sacred forest, and Khasi oral epics.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'jaintia-hills', 'meghalaya', 'Jaintia Hills', '{"West Jaintia Hills","East Jaintia Hills"}', 'Mineral-rich highlands celebrated for Nartiang monoliths, Behdeinkhlam festival, and crystal-clear Umngot river at Dawki.', 'Stone megaliths, sacred water ceremonies, and turmeric farming.'
            ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, cultural_character=EXCLUDED.cultural_character;
INSERT INTO state_sub_regions (id, state_id, name, districts, description, cultural_character) VALUES (
                'garo-hills', 'meghalaya', 'Garo Hills', '{"West Garo Hills","East Garo Hills","South Garo Hills"}', 'Western tropical forest range of the A-chik (Garo) people celebrated for the thunderous Wangala festival.', '100 Drums Wangala dance, Nokrek biosphere, and bamboo architectural pavilions.'
