-- CULTURAL ITEMS
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'pune-misal-pav', 'pune-misal-pav', 'Puneri Misal Pav', 'maharashtra', 'food', 'Sprouted moth bean curry spiced with indigenous Goda masala, layered with crisp farsan, chopped onions, and lemon, served with pav.', 'Puneri Misal is renowned for its balanced sweet, tangy, and pungent notes derived from roasted coconut, coriander seeds, and traditional Maharashtrian Goda Masala. Unlike Kolhapuri Misal, which is fiery red, Puneri Misal offers a layered complexity with poha or matki sprouts at its base, topped with crunchy farsan, spicy tarri (kat), chopped raw onions, fresh cilantro, and warm buttery pav.', 'Originated in the late 19th and early 20th centuries as a wholesome, protein-rich morning breakfast for agrarian workers and students in Pune’s historic peths (wards). Over decades, legendary institutions like Kata Kirr, Bedekar Tea Stall, and Shri Krishna Bhuvan perfected the dish into a cultural benchmark.', 'An emblem of Pune’s culinary identity, representing the Maharashtrian ethos of transforming simple sprouted pulses into a regal gastronomic experience.', '{"name":"Pune Peths","district":"Pune","state":"Maharashtra","coordinates":{"lat":18.5204,"lng":73.8567}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=80","alt":"Authentic Puneri Misal Pav served with spicy tarri and fresh lemons","credit":"Culinary Heritage Archives","license":"Creative Commons / Open Documentation"}]', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=80', '{"Misal","Pune","Goda Masala","Street Food","Breakfast","Vegetarian"}', '{"prepTime":"20 mins (+ overnight sprouting)","cookTime":"30 mins","difficulty":"Medium","ingredientsSummary":["1.5 cups sprouted Moth Beans (Matki)","2 tbsp authentic Maharashtrian Goda Masala","1 cup crunchy Mixed Farsan","1 large Onion, finely chopped","1 tsp Mustard seeds, Cumin seeds, and Curry leaves","Fresh Coriander, Lemon wedges, and Ladi Pav"],"culturalContext":"Traditionally cooked in iron kadhais to enhance the color and iron content of the tarri gravy.","recipeUrl":"https://recipes.timesofindia.com/recipes/puneri-misal/rs54332822.cms","verifiedSourceName":"Times of India Food Heritage"}', NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'mumbai-vada-pav', 'mumbai-vada-pav', 'Mumbai Vada Pav', 'maharashtra', 'food', 'Deep-fried spiced potato fritter (batata vada) encased in a soft ladi pav with fiery garlic chutney, fried green chilies, and mint chutney.', 'Often dubbed the "Indian Burger", Vada Pav is Mumbai’s ultimate democratic street food. It features a spiced mashed potato patty infused with mustard seeds, turmeric, ginger, garlic, and curry leaves, batter-coated in besan (gram flour) and fried golden. Served inside a sliced bun layered with pungent dry red garlic-coconut chutney and fried salted green chilies.', 'Created in 1966 by Ashok Vaidya outside Dadar railway station. Vaidya combined the traditional batata vada with western-style pav to create an ultra-portable, quick, and affordable meal for thousands of textile mill workers commuting along the central railway line.', 'A cornerstone of Mumbai’s working-class heritage and urban identity, crossing all socio-economic barriers.', '{"name":"Dadar, Mumbai","district":"Mumbai","state":"Maharashtra","coordinates":{"lat":19.0178,"lng":72.8478}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=1000&q=80","alt":"Classic Mumbai Vada Pav with dry garlic chutney and fried chilies","credit":"Mumbai Street Gastronomy Archive","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=1000&q=80', '{"Street Food","Mumbai","Vada Pav","Quick Meal","Working Class Heritage"}', '{"prepTime":"25 mins","cookTime":"20 mins","difficulty":"Easy","ingredientsSummary":["4 large boiled & mashed Potatoes","1 cup Besan (Gram Flour)","1 tbsp Ginger-Garlic-Green Chili crushed paste","1 tsp Mustard seeds, Turmeric, Asafoetida","1 cup Dry Red Garlic Coconut Chutney","6 fresh Ladi Pav buns & Fried salted Green Chilies"],"culturalContext":"Eaten on the go during daily suburban train commutes across the Mumbai metropolitan railway network.","recipeUrl":"https://hebbarskitchen.com/mumbai-vada-pav-recipe/","verifiedSourceName":"Indian Culinary Archives"}', NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'kolhapur-tambada-rassa', 'kolhapur-tambada-rassa', 'Kolhapuri Tambada & Pandhra Rassa', 'maharashtra', 'food', 'Legendary dual broths from Kolhapur — the fiery red broth infused with Lavangi chilies and the delicate white coconut-poppy seed broth.', 'Kolhapur’s royal culinary signature consists of two complementary broths: Tambada Rassa (a blazing red, aromatic mutton broth infused with stone-ground Kolhapuri Kanda-Lahsunkar Masala and Lavangi chilies) and Pandhra Rassa (a soothing, rich white broth prepared with coconut milk, white poppy seeds, cashew paste, and whole aromatic spices).', 'Perfected in the royal kitchens of the Chhatrapati rulers of Kolhapur. The hunting traditions (shikar) of the Maratha royalty necessitated wholesome, high-flavor broths that preserved natural meat juices while restoring vitality to warriors.', 'Represents the pinnacle of royal Maratha hospitality and meat preparation in southern Maharashtra.', '{"name":"Kolhapur City","district":"Kolhapur","state":"Maharashtra","coordinates":{"lat":16.705,"lng":74.2433}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1000&q=80","alt":"Kolhapuri Tambada and Pandhra Rassa served in traditional thali","credit":"Kolhapur Heritage Cuisine Consortium","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1000&q=80', '{"Kolhapur","Tambada Rassa","Pandhra Rassa","Royal Cuisine","Non-Vegetarian","Broth"}', '{"prepTime":"30 mins","cookTime":"45 mins","difficulty":"Advanced","ingredientsSummary":["500g bone-in tender Mutton pieces","2 tbsp Kolhapuri Kanda Lasun Masala","1 cup freshly pressed Coconut Milk (for Pandhra Rassa)","2 tbsp White Poppy Seeds (Khus Khus) and Cashew paste","Stone flower (Dagad Phool), Mace, Green Cardamom, Cinnamon","Fresh Coriander and Kolhapuri Lavangi Chilies"],"culturalContext":"Served as an unlimited broth course in Kolhapuri thalis alongside hot Bhakri (sorghum flatbread) and Indrayani rice.","recipeUrl":"https://food.ndtv.com/recipe-kolhapuri-tambda-rassa-953330","verifiedSourceName":"NDTV Food Heritage"}', NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'ukadiche-modak', 'ukadiche-modak', 'Ukadiche Modak', 'maharashtra', 'food', 'Steamed fragrant rice flour dumplings shaped like lotus buds, encasing a sweet filling of freshly grated coconut, jaggery, nutmeg, and cardamom, drizzled with pure ghee.', 'Ukadiche Modak is the spiritual crown jewel of Maharashtrian confectionery. The name translates to "steamed dumplings" (ukad meaning steaming). Prepared by kneading freshly ground fragrant rice flour into a delicate dough, it is expertly hand-pleated into flower-like folds containing a luscious filling of grated coconut cooked in sticky golden jaggery with fragrant nutmeg and cardamom.', 'Rooted in ancient Vedic and Puranic literature where Lord Ganesha is described as "Modakpriya" (the lover of Modaks). The 21-modak Naivedya has been offered across Maharashtra since medieval times during Ganesh Chaturthi.', 'The supreme sacred offering during Ganeshotsav, embodying motherly devotion, patience in hand-crafting 21 pleats, and auspiciousness.', '{"name":"Konkan Coast & Mumbai-Pune","district":"Ratnagiri","state":"Maharashtra","coordinates":{"lat":16.9902,"lng":73.312}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1567653418876-5bb0e566e1c2?auto=format&fit=crop&w=1000&q=80","alt":"Steamed Ukadiche Modak with saffron strands and pure ghee","credit":"Konkan Culinary Traditions","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1567653418876-5bb0e566e1c2?auto=format&fit=crop&w=1000&q=80', '{"Modak","Sweet","Ganesh Chaturthi","Steamed","Coconut","Jaggery"}', '{"prepTime":"40 mins","cookTime":"20 mins","difficulty":"Advanced","ingredientsSummary":["2 cups fragrant Ambemohar Rice Flour","2 cups freshly grated tender Coconut","1.5 cups organic sticky Jaggery (Gul)","1 tsp freshly ground Cardamom & Nutmeg powder","1 tbsp pure Cow Desi Ghee","Pinch of Saffron dissolved in warm milk"],"culturalContext":"Eaten piping hot with a generous spoonful of homemade golden cow ghee drizzled over the crest.","recipeUrl":"https://www.vegrecipesofindia.com/ukadiche-modak-recipe/","verifiedSourceName":"Authentic Maharashtrian Kitchen"}', NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'paithani-saree', 'paithani-saree', 'Paithani Silk Saree', 'maharashtra', 'fashion', 'The "Queen of Silks" hand-woven in Paithan with pure mulberry silk and real silver-gold zari, renowned for its peacock (Mor) and parrot motifs.', 'Paithani is one of India’s most opulent handloom textiles, characterized by its kaleidoscope-like oblique square borders and a heavy gold zari pallu adorned with peacocks, lotuses, and parrots. Woven using the ancient tapestry technique where weft threads are interlocked by hand rather than using a shuttle, a single authentic Paithani saree can take anywhere from six months to two years to complete.', 'Dates back to the 2nd century BCE Satavahana dynasty in the ancient capital of Pratishthana (modern-day Paithan). The craft enjoyed royal patronage under the Peshwas of Pune in the 18th century, who were passionate collectors and developed exclusive motifs like the Narali (coconut) border and Asawali (flowering creeper).', 'Regarded as a treasured family heirloom passed down through generations, indispensable in Maharashtrian weddings and royal festivities.', '{"name":"Paithan & Yeola","district":"Chhatrapati Sambhajinagar & Nashik","state":"Maharashtra","coordinates":{"lat":19.4795,"lng":75.3854}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=1000&q=80","alt":"Intricately woven gold zari pallu of an authentic royal Paithani saree","credit":"Maharashtra Handloom Weavers Guild","license":"Open Documentation"}]', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=1000&q=80', '{"Paithani","Saree","Handloom","Silk","Zari","Yeola","Bridal Heritage"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'kolhapuri-chappal', 'kolhapuri-chappal', 'Kolhapuri Chappal', 'maharashtra', 'fashion', 'GI-tagged handcrafted open-toed leather footwear cured with vegetable dyes and stitched entirely with leather cords without iron nails.', 'Kolhapuri Chappals are world-renowned hand-braided leather sandals produced in Kolhapur. The crafting process is 100% natural, using vegetable dyes derived from babul tree bark and harida seeds. Stitched purely using leather thread (without any metallic nails or synthetic glue), they are famed for their distinct squeak, durability, and intricate braided straps.', 'Dating back to the 13th century under the Shilahara rulers. In the early 20th century, Chhatrapati Shahu Maharaj of Kolhapur aggressively promoted the artisan community by establishing specialized tanning quarters and trade guilds.', 'Granted Geographical Indication (GI) status in 2019, celebrating centuries of artisanal leather tanning and knotting craftsmanship.', '{"name":"Kolhapur Artisan Quarters","district":"Kolhapur","state":"Maharashtra","coordinates":{"lat":16.705,"lng":74.2433}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=1000&q=80","alt":"Handcrafted authentic Kolhapuri leather sandals with braided detailing","credit":"Kolhapur Artisans Guild","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=1000&q=80', '{"Footwear","Leather","Kolhapur","GI Tag","Handmade","Artisanal"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'raigad-fort', 'raigad-fort', 'Raigad Fort — Capital of the Maratha Empire', 'maharashtra', 'forts', 'The impregnable hill bastion chosen by Chhatrapati Shivaji Maharaj as the capital of the Maratha Empire, site of his grand coronation in 1674.', 'Perched 820 meters (2,700 ft) above sea level in the Sahyadri mountain range, Raigad was engineered by master architect Hiroji Indulkar as an unassailable mountain capital. The fort features massive gateways (Maha Darwaja), the royal court (Raj Sabha) with acoustic marvels, the queens’ chambers, the marketplace, the legendary Hirakani Buruj cliff, and the sacred samadhi of Chhatrapati Shivaji Maharaj.', 'Captured from Chandrarao More in 1656, Shivaji Maharaj renovated and heavily fortified the wedge-shaped mountain, crowning it the capital of Hindavi Swarajya in his coronation ceremony on June 6, 1674. It remained the supreme seat of Maratha power for decades.', 'The emotional and political soul of Maharashtra, symbolizing self-rule, indigenous administrative wisdom, and military architectural brilliance.', '{"name":"Mahad Foothills","district":"Raigad","state":"Maharashtra","coordinates":{"lat":18.2346,"lng":73.4414}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1000&q=80","alt":"Mighty stone bastions and fog over Raigad Fort in Sahyadri mountains","credit":"ASI Western Circle & MTDC Archives","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1000&q=80', '{"Fort","Raigad","Shivaji Maharaj","Maratha Empire","Sahyadri","Capital"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'sinhagad-fort', 'sinhagad-fort', 'Sinhagad Fort — The Lion’s Fortress', 'maharashtra', 'forts', 'Historic hill fortress near Pune famed for the heroic 1670 battle led by Tanaji Malusare, who scaled its sheer cliff to recapture it.', 'Located 30 km southwest of Pune atop a cliff rising 1,312 meters above sea level, Sinhagad (originally Kondhana) offers sweeping tactical control over the Deccan plateau. The fort is revered for Tanaji Malusare’s night assault scaling the sheer vertical western cliff using a monitor lizard (Ghorpad named Yashwanti) during the Battle of Sinhagad in 1670.', 'Previously held by the Adil Shahi sultanate, the fort changed hands multiple times. Upon learning that Tanaji fell in the victorious battle, Shivaji Maharaj famously lamented: "Gad ala pan sinh gela" (The fort is won, but the lion is lost), renaming it Sinhagad.', 'A beloved pilgrimage and trekking landmark for Punekars, celebrated for its memorial to Tanaji, Kangan rock formations, and rustic culinary delights like hot Pithla-Bhakri and Matka Dahi.', '{"name":"Haveli Region","district":"Pune","state":"Maharashtra","coordinates":{"lat":18.3663,"lng":73.7558}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1627894006066-b45786537123?auto=format&fit=crop&w=1000&q=80","alt":"Sinhagad Fort stone gate and bastions overlooking the Pune plateau","credit":"Deccan Mountain Heritage Project","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1627894006066-b45786537123?auto=format&fit=crop&w=1000&q=80', '{"Sinhagad","Fort","Pune","Tanaji Malusare","Sahyadri","Trek"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'trimbakeshwar-temple', 'trimbakeshwar-temple', 'Trimbakeshwar Shiva Jyotirlinga', 'maharashtra', 'temples', 'One of the 12 sacred Jyotirlingas, situated at the source of the holy Godavari River at the foothills of the Brahmagiri mountain.', 'Trimbakeshwar Temple is an extraordinary black basalt stone shrine exhibiting classic Hemadpanthi and Nagara architecture. Uniquely, the Jyotirlinga here features three faces representing Brahma, Vishnu, and Shiva, topped with an ornate diamond-encrusted crown dating back to the Pandavas and Peshwas. The sacred Kushavarta kund within the complex is the symbolic source of the holy River Godavari.', 'Rebuilt in exquisite black stone by Peshwa Balaji Baji Rao (Nanasaheb Peshwa) between 1755 and 1786 CE on the ancient site where sage Gautama performed penance to bring the Godavari (Dakshin Ganga) down to Earth.', 'A supreme Hindu pilgrimage destination and one of the four hosts of the monumental Kumbh Mela held every 12 years in Nashik-Trimbak.', '{"name":"Trimbak, Brahmagiri Hills","district":"Nashik","state":"Maharashtra","coordinates":{"lat":19.932,"lng":73.5307}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1545128485-c400e7702796?auto=format&fit=crop&w=1000&q=80","alt":"Black stone carved shikhara of Trimbakeshwar Jyotirlinga Temple","credit":"Nashik Heritage Pilgrimage Trust","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1545128485-c400e7702796?auto=format&fit=crop&w=1000&q=80', '{"Jyotirlinga","Temple","Shiva","Nashik","Kumbh Mela","Godavari"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'lavani-dance', 'lavani-dance', 'Lavani — Vibrant Folk Dance & Rhythm', 'maharashtra', 'dance', 'A dynamic, rhythmic traditional folk dance performed to the rapid beats of the Dholki, famous for its expressiveness and Nauvari saree attire.', 'Lavani is Maharashtra’s most celebrated folk dance form, blending spirited dance, expressive facial abhinaya, and rapid footwork. Dancers don nine-yard Nauvari sarees, heavy ankle ghungroos (bells), and gold jewelry, performing to the pulsating polyrhythms of the wooden Dholki drum. Themes range from romance, satire, and social commentary to warrior valor.', 'Gained immense prominence during the 18th-century Peshwa era. Poets like Shahir Honaji Bala, Ram Joshi, and Prabhakar elevated Lavani into royal court entertainment and a morale-booster for Maratha soldiers returning from campaigns.', 'A cornerstone of Maharashtrian theater and rural sangeet baris, preserving indigenous rhythmic poetry and female expressive artistry.', '{"name":"Solapur, Kolhapur & Pune","district":"Solapur","state":"Maharashtra","coordinates":{"lat":17.6599,"lng":75.9064}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1000&q=80","alt":"Lavani folk dancer performing in vibrant Nauvari saree and ghungroos","credit":"Maharashtra Folk Arts Academy","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1000&q=80', '{"Lavani","Folk Dance","Dholki","Nauvari","Music","Performing Arts"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'powada-ballads', 'powada-ballads', 'Powada — Maratha Heroic Balladry', 'maharashtra', 'music', 'Dramatic narrative musical ballads composed by Shahirs (bard poets) narrating heroic battles, bravery, and historical sagas of Maratha warriors.', 'Powada is a dramatic vocal genre of heroic poetry accompanied by the Daf (tambourine-like drum), Dholki, and Majira cymbals. The Shahir (lead narrator) delivers rousing lyrical tales of military valor, strategy, and self-sacrifice with theatrical vigor, stirring deep patriotic and historical consciousness among listeners.', 'The earliest recorded Powada was composed in 1659 by Shahir Agnidas celebrating Chhatrapati Shivaji Maharaj’s victory over Afzal Khan at Pratapgad. During the Peshwa period, hundreds of ballads documented pivotal battles and social events.', 'A living oral history medium that preserved historical truth, military tactics, and moral fortitude across rural Maharashtra for over 350 years.', '{"name":"Satara & Raigad Heartlands","district":"Satara","state":"Maharashtra","coordinates":{"lat":17.6805,"lng":73.9997}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1000&q=80","alt":"Traditional Shahir performing Powada with Daf instrument","credit":"Maharashtra Sangeet & Folk Heritage Council","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1000&q=80', '{"Powada","Music","Ballad","Shahir","Shivaji Maharaj","Oral History"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'warli-painting', 'warli-painting', 'Warli Tribal Painting', 'maharashtra', 'crafts', 'Indigenous geometric tribal art created with rice paste on red ochre mud walls, depicting harmonious nature, farming, and the circular Tarpa dance.', 'Warli painting is one of the world’s oldest living tribal art traditions. Created predominantly by women of the Warli tribe in the Sahyadri mountains of northern Maharashtra, it uses basic geometric shapes — the circle (representing the sun and moon), triangle (representing mountains and conical trees), and square (representing sacred space or chauk). Pigment is made from ground rice paste mixed with water and gum, applied with a chewed bamboo stick over earth-colored clay backgrounds.', 'Traced back to the 10th century CE, with roots in Neolithic rock art traditions. Brought to global international prominence in the 1970s by master artist Jivya Soma Mashe, who transitioned the ritual wall art onto paper and canvas.', 'Granted GI status, Warli art represents an eco-centric worldview emphasizing human unity with forests, wildlife, and natural cycles without depicting anthropomorphic deities.', '{"name":"Dahanu & Jawhar Forests","district":"Palghar","state":"Maharashtra","coordinates":{"lat":19.91,"lng":73.12}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=1000&q=80","alt":"Warli tribal painting showing the circular Tarpa dance and village harmony","credit":"Tribal Research Institute of Maharashtra","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=1000&q=80', '{"Warli","Tribal Art","Palghar","Handicraft","GI Tag","Painting"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'ajanta-caves-murals', 'ajanta-caves-murals', 'Ajanta Caves — Ancient Rock Murals', 'maharashtra', 'temples', 'UNESCO World Heritage rock-cut Buddhist cave monuments featuring 2nd-century BCE tempera murals and masterly Jataka narrative paintings.', 'The 30 rock-cut cave monuments of Ajanta curve along a horseshoe-shaped basalt gorge over the Waghur River. Commissioned between the 2nd century BCE and the 5th century CE under the Satavahanas and Vakatakas, Ajanta represents the pinnacle of ancient Indian painting, celebrated for naturalistic anatomy, expressive hand mudras, and jewel-like mineral pigments.', 'Constructed in two distinct phases: early Hinayana Buddhist shrines under Satavahana patronage, followed by a monumental Mahayana artistic explosion during Emperor Harishena of the Vakataka dynasty (c. 460–477 CE).', 'A masterpiece of human creative genius on the UNESCO World Heritage list, providing the earliest visual benchmark of classical Indian fine art.', '{"name":"Waghur River Gorge","district":"Chhatrapati Sambhajinagar","state":"Maharashtra","coordinates":{"lat":20.5519,"lng":75.7033}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1000&q=80","alt":"Ajanta Cave facade carved into horseshoe basalt cliff","credit":"ASI Western Circle Archives","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1000&q=80', '{"Ajanta","Cave Murals","Buddhism","UNESCO","Rock-Cut Architecture"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'nagpur-tarri-poha', 'nagpur-tarri-poha', 'Nagpur Tarri Poha', 'maharashtra', 'food', 'Vidarbha’s fiery breakfast icon — flattened rice topped with spicy black-chana (chickpea) gravy, boiled potatoes, chopped onions, and crunchy sev.', 'Tarri Poha is the undisputed street food king of Nagpur and the Vidarbha region. Flattened rice (poha) tossed with mustard seeds, turmeric, and peanuts is served drowned in a boiling cauldron of fiery, red-hot tarri (gravy) loaded with whole kala chana (brown chickpeas). It is garnished with crisp sev, finely diced raw onions, fresh coriander, and a slice of lime.', 'Developed in eastern Maharashtra over the 20th century as a high-protein, calorie-dense breakfast for orange orchard workers and central railway transit travelers.', 'A cultural ritual in Nagpur where morning discussions across political and social lines unfold over steaming bowls of Tarri Poha.', '{"name":"Sitabuldi & Mahal","district":"Nagpur","state":"Maharashtra","coordinates":{"lat":21.1458,"lng":79.0882}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=80","alt":"Nagpuri Tarri Poha served with hot black chana gravy and crunchy sev","credit":"Vidarbha Gastronomy Archive","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=80', '{"Nagpur","Tarri Poha","Vidarbha","Street Food","Spicy","Breakfast"}', '{"prepTime":"20 mins","cookTime":"30 mins","difficulty":"Medium","ingredientsSummary":["2 cups thick flattened Rice (Poha)","1 cup boiled Black Chickpeas (Kala Chana)","2 tbsp Nagpuri Saoji Garam Masala","2 tbsp Ginger-Garlic paste & finely chopped Green Chilies","1 cup spiced Besan Sev & diced Onions","Fresh Lime wedges and chopped Coriander"],"culturalContext":"Served piping hot with customizable tarri spice levels from mild to fire-hot.","recipeUrl":"https://hebbarskitchen.com/tarri-poha-recipe/","verifiedSourceName":"Indian Culinary Archives"}', NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'pandharpur-wari-pilgrimage', 'pandharpur-wari-pilgrimage', 'Pandharpur Wari — Sacred Walking Pilgrimage', 'maharashtra', 'culture', 'An 800-year-old egalitarian walking pilgrimage of over one million Warkaris journeying on foot to the sacred temple of Lord Vitthala with Pakhawaj drums and cymbals.', 'The Pandharpur Wari is one of the world’s oldest and largest peaceful spiritual processions. Over one million pilgrims (Warkaris) walk barefoot for 21 days carrying the sacred silver padukas (footwear) of saint-poets Dnyaneshwar and Tukaram from Alandi and Dehu to the temple town of Pandharpur on the banks of the Bhima (Chandrabhaga) river.', 'Institutionalized in the 13th century by Saint Dnyaneshwar and Saint Namdev, and later reorganized into the modern Palkhi system by Haibatbaba Arfalkar in the 18th century.', 'A monumental living expression of equality, Bhakti philosophy, and social brotherhood transcending all caste, gender, and economic divisions.', '{"name":"Chandrabhaga River Bank","district":"Solapur","state":"Maharashtra","coordinates":{"lat":17.6775,"lng":75.3267}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1545128485-c400e7702796?auto=format&fit=crop&w=1000&q=80","alt":"Warkari pilgrims singing Abhangas with Pakhawaj drums on the way to Pandharpur","credit":"Warkari Heritage Foundation","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1545128485-c400e7702796?auto=format&fit=crop&w=1000&q=80', '{"Pandharpur","Wari","Bhakti","Warkari","Vitthala","Pilgrimage"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'ellora-kailasa-caves', 'ellora-kailasa-caves', 'Kailasa Temple — Monolithic Rock Excavation', 'maharashtra', 'temples', 'The world’s largest monolithic rock-cut structure, excavated top-down from a single basalt cliff in the 8th century by the Rashtrakuta dynasty.', 'Cave 16 of Ellora, known as the Kailasa Temple, is an unmatched zenith of Indian rock architecture. Unlike conventional temples constructed by stacking stone blocks, the Kailasa was carved vertically from top to bottom out of a single monolithic basalt mountain cliff. Over 200,000 tonnes of volcanic rock were removed over several decades to reveal a multi-storey Dravidian temple complete with life-sized sculpted elephants, monumental victory pillars (dhvajastambhas), and breathtaking bas-reliefs depicting the Ramayana and Mahabharata.', 'Commissioned in the 8th century CE (c. 756–773 CE) by King Krishna I of the Rashtrakuta dynasty. The master sculptors designed it as a physical representation of Mount Kailash, the sacred Himalayan abode of Lord Shiva.', 'A designated UNESCO World Heritage Site, universally recognized as one of the most astonishing architectural achievements in human civilization.', '{"name":"Ellora Caves Complex (Cave 16)","district":"Chhatrapati Sambhajinagar","state":"Maharashtra","coordinates":{"lat":20.0268,"lng":75.178}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1570168007204-dfb528c6958f?auto=format&fit=crop&w=1000&q=80","alt":"Monolithic carved shikhara and courtyard of Kailasa Temple at Ellora","credit":"ASI Aurangabad Circle & UNESCO Dossiers","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?auto=format&fit=crop&w=1000&q=80', '{"Ellora","Kailasa","UNESCO","Monolithic","Rashtrakuta","Rock-Cut Temple","Architecture"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'assam-muga-silk', 'assam-muga-silk', 'Assam Muga Golden Silk', 'assam', 'fashion', 'Naturally golden, ultra-durable wild silk hand-woven from endemic Antheraea assamensis silkworms across Sualkuchi textile villages.', 'Muga is one of the rarest wild silks on Earth, produced exclusively in the Brahmaputra Valley of Assam. Naturally lustrous with an unmistakable shimmer of molten gold, Muga silk possesses a remarkable property: its tensile strength and golden sheen increase with every wash. Woven into traditional Mekhela Chadors adorned with Kingkhap (royal Ahom crown) and floral motifs.', 'Patronized by the royal Ahom kings for over 600 years, who decreed that only royalty could wear pure Muga attire. The weaving knowledge has been preserved across generations in Sualkuchi, known as the "Manchester of Assam".', 'Granted GI status in 2007, Muga is integral to Assamese identity, worn during Bihu celebrations, weddings, and sacred rites as a mark of dignity and heritage.', '{"name":"Sualkuchi Weaving Cluster","district":"Kamrup","state":"Assam","coordinates":{"lat":26.1711,"lng":91.5727}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=1000&q=80","alt":"Golden luster of Assamese Muga silk Mekhela Chador with red Kingkhap borders","credit":"Directorate of Sericulture & Handloom, Assam","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=1000&q=80', '{"Muga Silk","Assam","Handloom","GI Tag","Mekhela Chador","Sualkuchi"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'bihu-dance', 'bihu-dance', 'Rongali Bihu Dance & Pepa Rhythms', 'assam', 'dance', 'Exuberant spring agrarian folk dance performed with rapid hand movements and swaying hips to the music of the Dhol, Pepa (buffalo horn pipe), and Gogona.', 'Bihu dance is the vibrant heartbeat of Assam, performed during the Bohag (Rongali) Bihu festival in mid-April to celebrate the arrival of the Assamese New Year and the spring seeding season. Both young men and women don traditional Muga silk Mekhela Chadors and Dhoti-Gamusas, dancing in concentric circles with rhythmic claps, hip sways, and brisk footwork that mimic agrarian planting and harvesting gestures.', 'Has ancient roots in Austroasiatic and Tibeto-Burman agrarian fertility rituals. In the 18th century, Ahom King Rudra Singha invited Bihu dancers to perform at the royal courtyard of Rang Ghar in Sivasagar, elevating the folk tradition into a national celebration.', 'A symbol of community fraternity, youthful joy, and seasonal renewal celebrated by all linguistic and ethnic communities of the Brahmaputra Valley.', '{"name":"Brahmaputra Valley & Sivasagar","district":"Sivasagar","state":"Assam","coordinates":{"lat":26.9826,"lng":94.6425}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1000&q=80","alt":"Assamese Bihu dancers in Muga silk and Kopou Phool orchid headpieces","credit":"Sangeet Natak Akademi Archives","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1000&q=80', '{"Bihu","Folk Dance","Assam","Pepa","Spring","Harvest"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'majuli-mukha-masks', 'majuli-mukha-masks', 'Majuli Island Mukha Mask Craft', 'assam', 'crafts', 'Traditional devotional theatrical masks sculpted from split bamboo frames, clay, cow dung, and vegetable dyes at Samaguri Satra on Majuli river island.', 'The Mukha mask-making tradition of Majuli Island was pioneered in the 16th century by Saint Srimanta Sankardev for use in Bhaona (religious folk theater). Artisans at Samaguri Satra craft lightweight, expressive masks representing mythological characters — from ten-headed Ravana and Garuda to gentle rishis. Constructed over a woven bamboo core layered with clay-soaked cotton fabric, they feature moving jaws and eyes.', 'Originated around 1500 CE as an audiovisual medium to convey Srimad Bhagavata moral narratives to rural communities regardless of literacy.', 'Granted GI status in 2024, preserving the living monastic arts of the world’s largest inhabited river island in the Brahmaputra.', '{"name":"Samaguri Satra, Majuli Island","district":"Majuli","state":"Assam","coordinates":{"lat":26.9535,"lng":94.2155}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=1000&q=80","alt":"Intricate handmade bamboo and clay Mukha mask at Samaguri Satra","credit":"Majuli Cultural Heritage Trust","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=1000&q=80', '{"Majuli","Masks","GI Tag","Assam","Bhaona","Handicraft","Bamboo"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'rang-ghar', 'rang-ghar', 'Rang Ghar — Ahom Royal Amphitheater', 'assam', 'architecture', 'Asia’s oldest surviving royal sports amphitheater, constructed in 1746 CE with indigenous sticky-rice mortar (Bora Saul) and an inverted-boat roof.', 'Rang Ghar ("House of Entertainment") is a two-storied red brick and stone amphitheater in Sivasagar, constructed by Ahom King Swargadeo Pramatta Singha in 1746 CE. From its royal pavilion, Ahom monarchs and nobility watched traditional sports such as buffalo fights, elephant wrestling, and Rongali Bihu performances. Its distinctive vaulted roof is shaped like an inverted Ahom war canoe (Maku).', 'A crowning engineering achievement of the Ahom Kingdom, showcasing seismic-resistant masonry constructed with brick paste blended with sticky rice (Bora Saul), duck eggs, and fish resin.', 'An enduring architectural symbol of Assam and one of the finest non-religious monuments in eastern India.', '{"name":"Rupahi Pathar, Sivasagar","district":"Sivasagar","state":"Assam","coordinates":{"lat":26.9644,"lng":94.6225}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1000&q=80","alt":"Historic red brick two-story structure of Rang Ghar in Sivasagar","credit":"Archaeological Survey of India, Guwahati Circle","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1000&q=80', '{"Rang Ghar","Assam","Ahom","Architecture","Sivasagar","Amphitheater"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'assam-masor-tenga', 'assam-masor-tenga', 'Assamese Masor Tenga (Sour Fish Curry)', 'assam', 'food', 'A light, refreshing sour fish broth prepared with fresh Rohu or Katla fish, wild elephant apple (Ou Tenga) or tomatoes, and tempered with panch phoran.', 'Masor Tenga is the quintessential comfort food of Assamese cuisine. Characterized by its light consistency and delicate sour palate, it derives its tartness from natural ingredients such as sun-dried Thekera (Garcinia pedunculata), Ou Tenga (elephant apple), lime juice, or green tomatoes. Flavored minimally with mustard oil, fenugreek seeds, and fresh green chilies to highlight the pristine sweet flavor of fresh Brahmaputra freshwater fish.', 'A centuries-old culinary response to the tropical, humid climate of the Brahmaputra Valley, designed to stimulate digestion and provide natural cooling and hydration.', 'An indispensable dish in everyday Assamese households and celebratory feasts (Bhoj), exemplifying the Northeast culinary philosophy of subtle, unmasked natural flavors.', '{"name":"Brahmaputra Riverfront","district":"Jorhat","state":"Assam","coordinates":{"lat":26.7509,"lng":94.2037}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1000&q=80","alt":"Refreshing light golden Masor Tenga with fresh fish and lemon garnish","credit":"Assam Gastronomy & Culinary Archives","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1000&q=80', '{"Masor Tenga","Assam","Fish","Sour Curry","Culinary Heritage","Brahmaputra"}', '{"prepTime":"15 mins","cookTime":"20 mins","difficulty":"Easy","ingredientsSummary":["500g fresh Rohu or Katla fish steaks","1 medium Ou Tenga (Elephant Apple) or 2 large Tomatoes, chopped","2 tbsp pure Mustard Oil","1 tsp Panch Phoran (Assamese five-spice blend) or Fenugreek seeds","1/2 tsp Turmeric powder & 3 slit Green Chilies","Fresh Coriander leaves & Lemon juice to finish"],"culturalContext":"Served as the main lunch curry alongside piping hot Joha aromatic sticky rice and boiled greens (Xaak).","recipeUrl":"https://www.thespruceeats.com/assamese-sour-fish-curry-recipe-1957597","verifiedSourceName":"Assam Heritage Kitchen"}', NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'meghalaya-living-root-bridge', 'meghalaya-living-root-bridge', 'Living Root Bridges (Jingkieng Jri)', 'meghalaya', 'architecture', 'Centuries-old bio-engineered suspension bridges grown by the indigenous Khasi and Jaintia tribes from aerial roots of Ficus elastica trees.', 'The Living Root Bridges (locally known as Jingkieng Jri) of Meghalaya are unmatched marvels of sustainable bio-engineering. Guided across raging monsoon streams using hollowed betel nut trunks, the aerial roots of the rubber fig tree (Ficus elastica) gradually interlock with stone boulders over 15 to 30 years. Unlike conventional timber or iron bridges that decay in the world’s wettest rainforests, Living Root Bridges grow stronger with age, capable of supporting up to 50 people simultaneously and surviving for over 500 years.', 'Practiced for centuries by the indigenous Khasi and Jaintia communities of the southern Meghalaya escarpment. The famous "Umshiang Double Decker Living Root Bridge" in Nongriat village was grown across two levels to accommodate rising monsoon water levels.', 'Nominated for UNESCO World Heritage status, representing an ancient paradigm of regenerative indigenous architecture where human mobility harmonizes completely with living ecosystems.', '{"name":"Nongriat & Sohra (Cherrapunji)","district":"East Khasi Hills","state":"Meghalaya","coordinates":{"lat":25.2758,"lng":91.6811}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1627894006066-b45786537123?auto=format&fit=crop&w=1000&q=80","alt":"Umshiang Double Decker Living Root Bridge spanning a crystal mountain river in Meghalaya","credit":"Meghalaya Tourism Development Corporation & Forest Department","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1627894006066-b45786537123?auto=format&fit=crop&w=1000&q=80', '{"Living Root Bridge","Meghalaya","Bio-Engineering","Khasi","Cherrapunji","UNESCO Tentative","Eco-Architecture"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'mawphlang-sacred-grove', 'mawphlang-sacred-grove', 'Mawphlang Sacred Grove (Law Kyntang)', 'meghalaya', 'tribal', 'An ancient untouched primeval rainforest preserved by the Khasi Lyngdoh clan for over 800 years under the sacred taboo: "Take nothing out of the forest."', 'Mawphlang Sacred Grove (Law Kyntang) is a biodiversity sanctuary spanning 76 hectares in the East Khasi Hills. Guarded by ancient tribal law, not a single leaf, twig, pebble, or fruit may be removed from the forest under penalty of invoking the guardian spirit deity, Labasa. As a result, the forest has remained untouched for over eight centuries, harboring endangered medicinal flora, ancient monolith stone sacrifice altars, rare orchids, and ancient ferns.', 'Established in the 12th century by the Lyngdoh clan after winning local clan conflicts. The forest contains ancient stone megalith coronations where Khasi chieftains signed treaties.', 'One of the world’s most profound examples of indigenous ecological conservation through sacred community belief systems.', '{"name":"Mawphlang Village","district":"East Khasi Hills","state":"Meghalaya","coordinates":{"lat":25.4497,"lng":91.7588}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1000&q=80","alt":"Ancient mossy trees and stone sacrificial monoliths inside Mawphlang Sacred Grove","credit":"Khasi Hills Autonomous District Council","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1000&q=80', '{"Sacred Grove","Meghalaya","Mawphlang","Khasi","Rainforest","Tribal Lore","Conservation"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'shad-suk-mynsiem', 'shad-suk-mynsiem', 'Shad Suk Mynsiem (Dance of Peaceful Hearts)', 'meghalaya', 'dance', 'The sacred annual spring thanksgiving dance of the Khasi people, celebrated with gold crowns, coral bead necklaces, and silver arrows.', 'Shad Suk Mynsiem ("Dance of the Joyful Hearts") is the premier cultural thanksgiving festival of the indigenous Khasi community in Meghalaya. Held in Shillong every April, unmarried young women dance in the inner circle with slow, graceful, dignified steps, while armed young men with silver quivers, peacock feather arrows, and fly-whisks circle the outer perimeter to symbolize their duty as protectors of women and the matrilineal clan.', 'A foundational spiritual expression of Ka Niam Khasi (the traditional Khasi faith), celebrating the cyclical renewal of nature, human gratitude to God the Creator (U Blei), and fertile agrarian harvests.', 'Demonstrates the matrilineal ethos of Khasi culture, where women are honored as the lineage holders and men serve as protectors and administrators.', '{"name":"Weiking Ground, Jaiaw, Shillong","district":"East Khasi Hills","state":"Meghalaya","coordinates":{"lat":25.5788,"lng":91.8933}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1000&q=80","alt":"Khasi dancers in gold crowns and red silk attire at Shad Suk Mynsiem in Shillong","credit":"Seng Khasi Heritage Organization","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1000&q=80', '{"Shad Suk Mynsiem","Khasi","Meghalaya","Folk Dance","Thanksgiving","Shillong"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'khasi-jadoh', 'khasi-jadoh', 'Khasi Jadoh (Aromatic Rice & Spices)', 'meghalaya', 'food', 'Iconic Khasi specialty made of indigenous red rice cooked in aromatic meat broth, scented with ginger, black sesame (Nei-lieh), and wild bay leaves.', 'Jadoh ("Ja" meaning rice, "Doh" meaning meat) is the cornerstone dish of Khasi culinary heritage. Prepared with indigenous Meghalayan short-grain red hill rice (Jashulia), the rice is slow-cooked in a rich meat broth infused with stone-ground ginger, garlic, crushed black pepper, and toasted black sesame seeds (Nei-lieh). It is celebrated for its deep earthy fragrance, moist texture, and absence of heavy commercial oils.', 'Developed by high-altitude Khasi mountain dwellers as a sustaining, warming meal suited for the cold, misty climate of the Meghalayan plateau.', 'Served across local Khasi teashops (Sha Dukan) in Shillong and during clan gatherings, accompanied by spicy fermented soybean chutney (Tungrymbai) and pickled bamboo shoots.', '{"name":"Iewduh (Bara Bazaar), Shillong","district":"East Khasi Hills","state":"Meghalaya","coordinates":{"lat":25.5788,"lng":91.88}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=80","alt":"Authentic steaming Khasi Jadoh red rice served with fresh herbs","credit":"Khasi Indigenous Gastronomy Project","license":"Open Access Documentation"}]', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=80', '{"Jadoh","Khasi","Meghalaya","Rice","Culinary","Shillong","Street Food"}', '{"prepTime":"20 mins","cookTime":"35 mins","difficulty":"Medium","ingredientsSummary":["2 cups authentic Meghalayan Red Rice or Short-grain rice","400g tender bone-in chicken or pork chunks","2 tbsp toasted and crushed Black Sesame seeds (Nei-lieh)","2-inch piece fresh Ginger & 8 cloves Garlic, finely crushed","2 wild Bay leaves & 1 chopped Onion","Fresh Green Chilies, Black Pepper, and Mustard Oil"],"culturalContext":"Traditionally cooked in heavy brass vessels over wood-fired mountain stoves to impart an unmistakable smoky aroma.","recipeUrl":"https://northeasttourism.gov.in/food/jadoh","verifiedSourceName":"North East Culinary Heritage"}', NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;
INSERT INTO cultural_items (id, slug, title, state_id, category, short_description, description, history, cultural_significance, location_name, latitude, longitude, images, primary_image, tags, recipe_info, model_3d_id) VALUES (
        'rajasthan-kathputli', 'rajasthan-kathputli', 'Kathputli String Puppetry', 'rajasthan', 'crafts', 'Centuries-old wooden string puppetry from the Thar Desert depicting chivalric ballads of Amar Singh Rathore.', 'Kathputli is a traditional string puppet theater native to Rajasthan, carved from mango wood and dressed in bright Rajasthani bandhani and gota-patti fabrics.', 'Practiced for over a millennium by the Bhatt community of Rajasthan.', 'One of the earliest recorded performing arts of northern India.', '{"name":"Jaipur & Jodhpur","district":"Jaipur","state":"Rajasthan","coordinates":{"lat":26.9124,"lng":75.7873}}', NULL, NULL, '[{"url":"https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1000&q=80","alt":"Rajasthani Kathputli puppets with colorful bandhani skirts","credit":"Rajasthan Folk Heritage Trust","license":"Open Access"}]', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1000&q=80', '{"Kathputli","Rajasthan","Puppetry","Folk Art"}', NULL, NULL
    ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description, description=EXCLUDED.description, history=EXCLUDED.history, cultural_significance=EXCLUDED.cultural_significance, location_name=EXCLUDED.location_name;

