INSERT INTO festivals (id, name, month_index, date_or_season, upcoming_date, day_or_tithi, state, state_id, category, image, short_description, cultural_significance) VALUES (
        'bihu', 'Rongali (Bohag) Bihu', 3, 'Bohag Month (Mid-April)', 'April 14, 2026', '1st Day of Bohag', 'Assam', 'assam', 'harvest', 'https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1000&q=80', 'The 7-day Assamese spring and agrarian New Year festival celebrated with spirited Bihu dance, Pepa horn calls, and Pitha sweets.', 'Marks the start of the agrarian calendar, honors cattle (Goru Bihu), ancestors, and the rejuvenation of nature.'
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, date_or_season=EXCLUDED.date_or_season, upcoming_date=EXCLUDED.upcoming_date, state=EXCLUDED.state, short_description=EXCLUDED.short_description;
INSERT INTO festivals (id, name, month_index, date_or_season, upcoming_date, day_or_tithi, state, state_id, category, image, short_description, cultural_significance) VALUES (
        'shad-suk-mynsiem-fest', 'Shad Suk Mynsiem', 3, 'Mid-April (Spring Thanksgiving)', 'April 18, 2026', 'Khasi Lunar Spring Cycle', 'Meghalaya', 'meghalaya', 'seasonal', 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1000&q=80', 'The "Dance of the Peaceful Hearts" celebrated by the Khasi people in Shillong as a majestic thanksgiving to the Creator for fertile rains.', 'Highlights the matrilineal structure of Khasi society, with women dancing in pure silver-gold crowns encircled by male protectors.'
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, date_or_season=EXCLUDED.date_or_season, upcoming_date=EXCLUDED.upcoming_date, state=EXCLUDED.state, short_description=EXCLUDED.short_description;
INSERT INTO festivals (id, name, month_index, date_or_season, upcoming_date, day_or_tithi, state, state_id, category, image, short_description, cultural_significance) VALUES (
        'pola-festival', 'Bail Pola (Bullock Thanksgiving)', 7, 'Shravan/Bhadrapada Purnima (August)', 'August 28, 2026', 'Pithori Amavasya', 'Maharashtra', 'maharashtra', 'harvest', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1000&q=80', 'A heart-touching rural agrarian festival honoring farm bullocks and cattle that labor alongside farmers year-round.', 'Farmers wash, decorate horns with paint and ornaments, and bow to their bulls, exempting them from work on this sacred day.'
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, date_or_season=EXCLUDED.date_or_season, upcoming_date=EXCLUDED.upcoming_date, state=EXCLUDED.state, short_description=EXCLUDED.short_description;
INSERT INTO festivals (id, name, month_index, date_or_season, upcoming_date, day_or_tithi, state, state_id, category, image, short_description, cultural_significance) VALUES (
