INSERT INTO festivals (id, name, month_index, date_or_season, upcoming_date, day_or_tithi, state, state_id, category, image, short_description, cultural_significance) VALUES (
        'durga-puja', 'Durga Puja', 9, 'Ashwin Month (Sep–Oct)', 'October 18, 2026', 'Maha Saptami to Dashami', 'West Bengal', 'west-bengal', 'religious', 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?auto=format&fit=crop&w=1000&q=80', 'UNESCO Intangible Cultural Heritage celebrating the victory of Goddess Durga over Mahishasura through grand artistic pandals.', 'A monumental public celebration uniting visual arts, dhak percussion, classical literature, and community banquets.'
