INSERT INTO festivals (id, name, month_index, date_or_season, upcoming_date, day_or_tithi, state, state_id, category, image, short_description, cultural_significance) VALUES (
        'wangala-fest', 'Wangala (100 Drums Festival)', 10, 'Post-Harvest (Second Week of November)', 'November 12, 2026', 'Garo Post-Harvest Moon', 'Meghalaya', 'meghalaya', 'harvest', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1000&q=80', 'The most significant post-harvest festival of the Garo (A-chik) tribe, honoring Saljong (the Sun God of fertility) with 100 synchronized long drums.', 'Men in feathered headdresses (Do’kisha) beat 100 Dama drums simultaneously while women dance to invoke blessings for future crops.'
