INSERT INTO festivals (id, name, month_index, date_or_season, upcoming_date, day_or_tithi, state, state_id, category, image, short_description, cultural_significance) VALUES (
        'pushkar-fair', 'Pushkar Camel Fair', 10, 'Kartik Purnima (Oct–Nov)', 'November 22, 2026', 'Kartik Shukla Ekadashi to Purnima', 'Rajasthan', 'rajasthan', 'art', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1000&q=80', 'One of the world’s largest camel and cultural fairs set against the sacred dunes and ghats of Lake Pushkar.', 'A vibrant confluence of pastoral traditions, folk music, Rajasthani textiles, and sacred pilgrimage rituals.'
