-- MONUMENTS
INSERT INTO monuments (id, slug, name, state, state_id, region, district_or_city, category, short_description, description, detailed_history, cultural_importance, location_name, year_built, architectural_style, image, banner_image, latitude, longitude) VALUES (
        'ellora-caves', 'ellora-caves', 'Kailasa Temple, Ellora Caves', 'Maharashtra', 'maharashtra', 'Marathwada', NULL, 'Monolithic Rock-Cut Architecture', 'The world’s largest monolithic rock-cut structure, carved top-down from a single volcanic basalt mountain cliff.', 'Commissioned under Rashtrakuta King Krishna I in the 8th century CE, Cave 16 (Kailasa Temple) was excavated vertically downward from a basalt cliff without scaffolding or structural joints. Over 200,000 tonnes of volcanic rock were removed by hand to reveal a multistory Dravidian temple sanctuary adorned with sculpted elephants and epic Ramayana bas-reliefs.', 'Commissioned under Rashtrakuta King Krishna I (c. 756–773 CE), Cave 16 (Kailasa Temple) was excavated vertically downward from a basalt escarpment. An estimated 200,000 tonnes of volcanic rock were removed by hand chiseling over several decades, leaving a monumental multi-story temple complex with sanctuary, mandapa, life-size elephant sculptures, and mythological relief panels without the use of masonry joints or external support columns.', 'A UNESCO World Heritage Site exemplifying harmony across Hindu, Buddhist, and Jain cave art in close geographic proximity.', 'Verul, Chhatrapati Sambhajinagar (Aurangabad)', '8th Century CE (c. 756–773 CE)', 'Monolithic Dravidian Rock-Cut', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1600&q=80', 20.0268, 75.178
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, short_description=EXCLUDED.short_description, description=EXCLUDED.description, detailed_history=EXCLUDED.detailed_history, image=EXCLUDED.image;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'vimana-shikhara', 'ellora-caves', 'Dravidian Shikhara (Main Spire)', '30-meter high monolithic pyramidal spire carved top-down.', 'The main sanctuary tower (Vimana) rises nearly 30 meters high. It was carved first from the crest of the cliff downward before the surrounding courtyards were cleared.', 0, 6, -2, 0, 9, 10, 0, 6, -2, NULL, 'Solid carved basalt stone with octagonal dome crowning'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'dhwajasthambha', 'ellora-caves', 'Monolithic Victory Pillar (Dhwajastambha)', 'Pair of freestanding 15-meter ceremonial columns.', 'Two gigantic freestanding victory pillars stand in the main courtyard, carved directly in-situ from the solid volcanic rock bed with trident crests.', -3.5, 2.5, 2, -6, 4, 8, -3.5, 2.5, 2, NULL, 'In-situ monolithic basalt column with Trishula finial'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'elephant-plinth', 'ellora-caves', 'Life-Sized Elephant Plinth', 'Colossal elephant frieze creating the illusion of carrying the entire temple.', 'The entire temple plinth is supported by a continuous relief of life-sized elephants, lions, and mythical beasts carved into the lower terrace bedrock.', 2.5, 0.8, 1.2, 5, 2, 6, 2.5, 0.8, 1.2, NULL, 'High-relief volcanic basalt stone carving'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monuments (id, slug, name, state, state_id, region, district_or_city, category, short_description, description, detailed_history, cultural_importance, location_name, year_built, architectural_style, image, banner_image, latitude, longitude) VALUES (
        'gateway-of-india', 'gateway-of-india', 'Gateway of India', 'Maharashtra', 'maharashtra', 'Konkan', NULL, 'Indo-Saracenic Triumphal Arch', 'Monumental yellow basalt archway on the Arabian Sea waterfront, fusing 16th-century Gujarati architecture with classical European triumphal design.', 'Designed by Scottish architect George Wittet, the Gateway of India stands on the historic Apollo Bunder waterfront facing Mumbai Harbour. Constructed from indigenous yellow basalt and reinforced concrete, it combines Gujarati jali lattices with classical Roman triumphal arches. Historically the ceremonial landing port of India, it was also the ceremonial departure point of the last British troops in 1948.', 'Designed by George Wittet, the Gateway of India was constructed to commemorate the visit of King George V and Queen Mary in 1911. The monument stands on Apollo Bunder facing the Arabian Sea and historically served as the ceremonial entrance to India. Paradoxically, it was also the point through which the last British regiment (First Battalion of the Somerset Light Infantry) departed India on February 28, 1948, marking the end of colonial rule.', 'An enduring civic symbol of Mumbai, uniting coastal basalt masonry, intricate jali lattice work, and Indo-Islamic domes.', 'Apollo Bunder, Colaba, Waterfront Mumbai', '1911–1924', 'Indo-Saracenic Revival', 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?auto=format&fit=crop&w=1600&q=80', 18.922, 72.8347
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, short_description=EXCLUDED.short_description, description=EXCLUDED.description, detailed_history=EXCLUDED.detailed_history, image=EXCLUDED.image;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'central-arch', 'gateway-of-india', 'Central Triumphal Arch', 'Grand 26-meter basalt archway with Gujarati vaulting.', 'The main arch rises 26 meters (85 feet) above the waterfront plaza. Constructed from yellow basalt quarried in Thane, its proportions echo classical Roman triumphal designs with Islamic arched contours.', 0, 2.5, 1.2, 0, 3, 8, 0, 2.5, 1.2, NULL, 'Yellow basalt masonry with perforated screen accents'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'central-dome', 'gateway-of-india', 'Central Ribbed Dome', 'Indo-Islamic dome spanning 15 meters in diameter with ornamental spires.', 'The central dome features an internal diameter of 15 meters and is crowned by four decorative side turrets. The structural load is distributed across massive stone buttresses.', 0, 5.2, 0, 0, 7, 10, 0, 5.2, 0, NULL, 'Reinforced concrete shell with stone cladding'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'latticed-screens', 'gateway-of-india', 'Gujarati Jali Screen Windows', 'Intricate basalt jaali lattice panels carved in 16th-century Sultanate style.', 'The lateral arches feature delicately carved pierced stonework screens (jalis), providing structural ventilation and shade while referencing the architectural lineage of Champaner and Ahmedabad.', -2.8, 1.8, 0.8, -5, 2.5, 5, -2.8, 1.8, 0.8, NULL, 'Fine-grain basalt pierced filigree'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'seafront-promenade', 'gateway-of-india', 'Arabian Sea Anchorage Steps', 'Ceremonial stone steps descending to the historic Apollo Bunder jetty.', 'The seaward approach once welcomed maritime dignitaries arriving by steamer and today connects citizens with historic ferry routes to Elephanta Caves.', 0, 0.2, 3.5, 0, 1.5, 7, 0, 0.2, 3.5, NULL, 'Tide-resistant granite foundations'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monuments (id, slug, name, state, state_id, region, district_or_city, category, short_description, description, detailed_history, cultural_importance, location_name, year_built, architectural_style, image, banner_image, latitude, longitude) VALUES (
        'raigad-fort-shivaji-statue', 'raigad-fort-shivaji-statue', 'Chhatrapati Shivaji Maharaj Statue & Samadhi, Raigad Fort', 'Maharashtra', 'maharashtra', 'Konkan (Sahyadris)', NULL, 'Maratha Imperial Architecture & Memorial', 'The solemn royal memorial canopy (Meghadambari) and equestrian bronze statue commemorating Chhatrapati Shivaji Maharaj at his coronation capital atop Raigad.', 'Perched 820 meters high atop the wedge-shaped Gibraltar of the East in the Sahyadri mountains, the Samadhi of Chhatrapati Shivaji Maharaj and the ceremonial Meghadambari canopy represent the spiritual heart of the Maratha Empire. Designed originally with acoustic precision by royal architect Hiroji Indulkar, the complex overlooks the grand Rajsabha (Coronation Throne Room) and the historic Nagarkhana gateway.', 'Raigad Fort was selected by Chhatrapati Shivaji Maharaj as the capital of the sovereign Swarajya and was the site of his grand coronation (Rajyabhisheka) on June 6, 1674. Following his passing in 1680, his Samadhi was consecrated adjacent to the Jagadishwar Temple. In the 20th century, the historic memorial was restored under the guidance of Lokmanya Tilak and Maharashtra heritage preservation societies with an imposing seated bronze statue sheltered by the traditional stone Meghadambari canopy.', 'The spiritual beacon of Swarajya (Self-Rule), democratic decentralization, and mountain fortress engineering in western India.', 'Raigad Fort Plateau, Mahad Taluka, Raigad', '1674 CE (Coronation) / 1680 CE (Samadhi)', 'Maratha Fortified Basalt & Meghadambari Canopy', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1600&q=80', 18.2347, 73.4414
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, short_description=EXCLUDED.short_description, description=EXCLUDED.description, detailed_history=EXCLUDED.detailed_history, image=EXCLUDED.image;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'meghadambari-canopy', 'raigad-fort-shivaji-statue', 'Stone Meghadambari Canopy', 'Carved stone umbrella canopy sheltering the royal statue.', 'The Meghadambari is a four-pillared ornamental basalt pavilion crowning the seated statue, adorned with traditional Maratha floral carvings and Kalash finials.', 0, 3.2, 0, 0, 4.5, 8, 0, 3.2, 0, NULL, 'Chiseled Sahyadri basalt with traditional chhatri pavilion vaulting'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'samadhi-plinth', 'raigad-fort-shivaji-statue', 'Sacred Samadhi Memorial Plinth', 'Octagonal stone foundation of the Maharaja’s final resting place.', 'Positioned in the quiet northern terrace of the hill fort beside the Jagadishwar Temple, with floral offerings maintained daily according to Vedic rituals.', 0, 0.8, -1.5, 0, 2.5, 5, 0, 0.8, -1.5, NULL, 'Octagonal dressed basalt stone masonry plinth'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'nagarkhana-view', 'raigad-fort-shivaji-statue', 'Nagarkhana & Acoustic Royal Court', 'Grand ceremonial entrance with acoustic parabolic amplification.', 'Engineered by Hiroji Indulkar so that a whisper at the entrance arch could be heard clearly 75 meters away at the royal throne, without electronic amplification.', -3.5, 2, 3, -6, 3.5, 7, -3.5, 2, 3, NULL, 'Basalt acoustic vaulted archway'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monuments (id, slug, name, state, state_id, region, district_or_city, category, short_description, description, detailed_history, cultural_importance, location_name, year_built, architectural_style, image, banner_image, latitude, longitude) VALUES (
        'living-root-bridge', 'living-root-bridge', 'Double Decker Living Root Bridge (Jingkieng Jri)', 'Meghalaya', 'meghalaya', 'Khasi Hills', NULL, 'Khasi Botanical Bio-Engineering', 'Two-tier regenerative pedestrian bridge guided across torrential mountain waters from the living aerial roots of Ficus elastica trees.', 'Grown over multiple generations by the indigenous Khasi people of Nongriat village in the subtropical rainforests of Meghalaya, the Double Decker Living Root Bridge (Jingkieng Jri) is a self-strengthening botanical marvel. Aerial roots of the Indian Rubber Tree are guided across hollowed betel nut trunks. Unlike steel or concrete bridges that rot in extreme monsoon humidity, living root bridges become stronger and thicker every decade.', 'Grown over generations by the Khasi people of Nongriat. The second upper tier was grown when extreme monsoon river swelling threatened the lower pathway. Unlike concrete or iron structures that disintegrate in the hyper-humid climate of Cherrapunji, living root bridges become stronger and more secure every decade as roots intertwine and thicken.', 'A global masterpiece of regenerative indigenous engineering on the UNESCO World Heritage tentative list.', 'Nongriat Village, Sohra (Cherrapunji) Valley', 'Over 250+ Years (Living Adaptive Structure)', 'Indigenous Khasi Botanical Bio-Engineering', 'https://images.unsplash.com/photo-1627894006066-b45786537123?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1627894006066-b45786537123?auto=format&fit=crop&w=1600&q=80', 25.2758, 91.6811
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, short_description=EXCLUDED.short_description, description=EXCLUDED.description, detailed_history=EXCLUDED.detailed_history, image=EXCLUDED.image;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'upper-tier-deck', 'living-root-bridge', 'Upper Living Root Deck', 'Secondary elevated span grown for high monsoon flood surges.', 'Added approximately 100 years after the primary bridge to ensure uninterrupted village connectivity when torrential monsoon waters submerged the lower pathway.', 0, 3.8, 0, 0, 5, 8, 0, 3.8, 0, NULL, 'Interwoven living secondary aerial roots with stone deck infill'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'lower-span', 'living-root-bridge', 'Primary Lower Bridge Span', 'Original 250-year-old walking platform over the Umshiang River.', 'Spanning over 20 meters across the roaring torrent, capable of supporting over 50 pedestrians simultaneously through root anastomosing.', 0, 1.8, 0, 0, 3, 7, 0, 1.8, 0, NULL, 'Fused Ficus elastica root network'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'anchor-boulders', 'living-root-bridge', 'Basalt Boulder Anchors', 'Riverbed stone monoliths entwined by living root tendrils.', 'Roots wrap tightly around riverside granite boulders, utilizing natural stone mass as permanent cantilever ballast.', -2.5, 0.8, 1.5, -5, 2, 5, -2.5, 0.8, 1.5, NULL, 'Bio-integrated stone root anchors'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monuments (id, slug, name, state, state_id, region, district_or_city, category, short_description, description, detailed_history, cultural_importance, location_name, year_built, architectural_style, image, banner_image, latitude, longitude) VALUES (
        'rang-ghar', 'rang-ghar', 'Rang Ghar, Sivasagar', 'Assam', 'assam', 'Upper Assam (Brahmaputra Valley)', NULL, 'Tai-Ahom Royal Pavilion', 'Asia’s oldest royal sports amphitheater with an inverted-boat vaulted roof, constructed with organic sticky-rice bio-mortar.', 'Commissioned by Ahom King Swargadeo Pramatta Singha in 1746 CE, Rang Ghar served as the grand royal amphitheater from which monarchs and dignitaries enjoyed traditional sports, buffalo fights, and Rongali Bihu performances. Its seismic-resilient construction used indigenous bricks bonded with sticky rice, duck eggs, and fish paste.', 'Commissioned by Ahom King Swargadeo Pramatta Singha in 1746 CE, Rang Ghar served as the grand royal amphitheater from which kings and dignitaries enjoyed traditional sports, bull fights, and Rongali Bihu performances. Its seismic-resilient construction used indigenous bricks bonded with sticky rice, duck eggs, and fish paste.', 'An enduring secular architectural symbol of the 600-year Ahom Kingdom.', 'Sivasagar Ahom Royal Capital, Assam', '1746 CE', 'Tai-Ahom Brick & Rice Mortar Pavilion', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=1600&q=80', 26.9644, 94.6225
    ) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, short_description=EXCLUDED.short_description, description=EXCLUDED.description, detailed_history=EXCLUDED.detailed_history, image=EXCLUDED.image;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'inverted-boat-roof', 'rang-ghar', 'Inverted-Boat Vaulted Roof', 'Parabolic roof profile modeled after traditional Tai-Ahom longboats.', 'The curved masonry roof draws direct inspiration from Ahom royal war boats (Maku), providing rapid monsoon drainage and wind deflection.', 0, 4.8, 0, 0, 6.5, 9, 0, 4.8, 0, NULL, 'Curvilinear brick vaulting with clay tile crowning'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
INSERT INTO monument_hotspots (id, monument_id, title, short_description, detailed_text, position_x, position_y, position_z, camera_position_x, camera_position_y, camera_position_z, camera_target_x, camera_target_y, camera_target_z, image_url, architectural_note) VALUES (
                'royal-viewing-pavilion', 'rang-ghar', 'Royal Upper Gallery', 'Arched open pavilion for Swargadeo monarchs.', 'The second tier accommodated the king and royal guests with panoramic vistas over the Rupahi Pathar sports arena.', 0, 2.8, 1.2, 0, 3.5, 6, 0, 2.8, 1.2, NULL, 'Segmental arched colonnades'
            ) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, short_description=EXCLUDED.short_description;
